SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='ef2d7ed3-ee87-5bb5-aac8-343b2c272e10'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('db3d7cfc-fc9f-5933-951e-a0f43fa9d09f','d96f35c2-3f4a-52dd-8292-4e94e6057ead')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='ef2d7ed3-ee87-5bb5-aac8-343b2c272e10'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='ef2d7ed3-ee87-5bb5-aac8-343b2c272e10'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('db3d7cfc-fc9f-5933-951e-a0f43fa9d09f','d96f35c2-3f4a-52dd-8292-4e94e6057ead')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='ef2d7ed3-ee87-5bb5-aac8-343b2c272e10'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='db3d7cfc-fc9f-5933-951e-a0f43fa9d09f' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='unique-control-different-subjects-identical-text-key' AND q.fingerprint='b5b980f8182c054e1a44ddc353d2bb164cd23222d26068e53108ea7bbadb38a7'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-race-different-subjects-identical-text-key-b","status":"ok","value":{"customerProfileId":"ef2d7ed3-ee87-5bb5-aac8-343b2c272e10","userId":"63ffc216-5055-5b5d-818d-e125e3aff027","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"db3d7cfc-fc9f-5933-951e-a0f43fa9d09f","semanticKey":"unique-control-different-subjects-identical-text-key","fingerprint":"b5b980f8182c054e1a44ddc353d2bb164cd23222d26068e53108ea7bbadb38a7","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='6955d0fb-2558-5e8d-abb9-7d5c5b03928b' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='43ee6e8c-4619-5765-8b8a-eb8416f9f7a3' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"ef2d7ed3-ee87-5bb5-aac8-343b2c272e10"},"prior":null,"committed":{"id":"ef2d7ed3-ee87-5bb5-aac8-343b2c272e10","userId":"63ffc216-5055-5b5d-818d-e125e3aff027","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='ef2d7ed3-ee87-5bb5-aac8-343b2c272e10' AND c.user_id='63ffc216-5055-5b5d-818d-e125e3aff027' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='unique-race-different-subjects-identical-text-key-b' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='76768d24-c67c-56c6-95e2-4ccd5411e0da' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"ef2d7ed3-ee87-5bb5-aac8-343b2c272e10","userId":"63ffc216-5055-5b5d-818d-e125e3aff027","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='449d9f17-4764-5a02-953e-d510c1355039' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"63ffc216-5055-5b5d-818d-e125e3aff027","track":"customer","customerProfileId":"ef2d7ed3-ee87-5bb5-aac8-343b2c272e10","sourceCreationRevision":"0","sourceCreationReceipt":"db3d7cfc-fc9f-5933-951e-a0f43fa9d09f","semanticKey":"customer_buyer_profile/ef2d7ed3-ee87-5bb5-aac8-343b2c272e10/default-free-enrollment/v1"}'::jsonb)))=2));
